/* Regression coverage for the rwav WAV reader.
 *
 * Eight tiny streams are embedded, one per decode arm: PCM at 8, 16
 * and 24 bits, IEEE float 32, A-law, mu-law, IMA ADPCM and MS ADPCM,
 * all cut from the same quarter-second sine so the lossless arms must
 * agree with each other exactly.  The reference checksums for the
 * companded and ADPCM arms were cross-validated byte-exact against
 * ffmpeg's decoders on the same streams when this suite was written.
 *
 * Checksums fold each decoded s16 as two canonical little-endian
 * bytes, so the expected values hold on big-endian hosts too - where
 * this suite is exercising the swab paths that little-endian CI never
 * compiles in.
 *
 * Four properties:
 *
 * 1. Every format decodes via rwav_parse + rwav_decode_s16 to its
 *    reference checksum and frame count.
 *
 * 2. rwav_load's owned payload agrees with rwav_decode_s16 for
 *    PCM16 - the two API paths must tell one story.
 *
 * 3. Windowed decoding equals whole-file decoding, for window sizes
 *    chosen to land mid-block: this pins the ADPCM block-window
 *    arithmetic, including the direct-into-caller fast path for
 *    block-aligned windows and the bounce path for the rest.
 *
 * 4. Truncation robustness: every header prefix and a sweep of
 *    payload truncations parse without crashing (run this suite
 *    under ASan for the memory half of that claim). */

#include <stdlib.h>
#include <string.h>
#include <stdint.h>

#include <check.h>

#include <formats/rwav.h>

#define SUITE_NAME "rwav"

